<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\Auth;use App\Core\Database;use App\Core\View;
final class DiscussionController
{
    public function index():void{$items=Database::all("SELECT d.*,c.name category,u.full_name,(SELECT COUNT(*) FROM discussion_comments x WHERE x.discussion_id=d.id AND x.status='approved') replies FROM discussions d JOIN discussion_categories c ON c.id=d.category_id JOIN users u ON u.id=d.user_id WHERE d.status IN('published','locked') AND d.deleted_at IS NULL ORDER BY d.is_pinned DESC,d.published_at DESC LIMIT 50");View::render('discussions/index',['discussions'=>$items]);}
    public function show(string $slug):void{$discussion=Database::one("SELECT d.*,c.name category,u.full_name FROM discussions d JOIN discussion_categories c ON c.id=d.category_id JOIN users u ON u.id=d.user_id WHERE d.slug=? AND d.status IN('published','locked') AND d.deleted_at IS NULL",[$slug]);if(!$discussion){http_response_code(404);View::render('errors/404',['title'=>'Discussion not found']);return;}$comments=Database::all("SELECT c.*,u.full_name FROM discussion_comments c JOIN users u ON u.id=c.user_id WHERE c.discussion_id=? AND c.status='approved' AND c.deleted_at IS NULL ORDER BY c.created_at LIMIT 200",[$discussion['id']]);View::render('discussions/show',compact('discussion','comments'));}
    public function create():void{Auth::requireLogin();$categories=Database::all('SELECT * FROM discussion_categories WHERE is_active=1 ORDER BY position');View::render('discussions/create',compact('categories'));}
    public function store():void{Auth::requireLogin();$title=trim($_POST['title']??'');$body=trim($_POST['body']??'');$category=(int)($_POST['category_id']??0);if(mb_strlen($title)<8||mb_strlen($body)<30||!$category){flash('error','Please add a clear title, category and detailed opening post.');redirect('discussions/create');}$slug=trim(preg_replace('/[^a-z0-9]+/i','-',strtolower(iconv('UTF-8','ASCII//TRANSLIT',$title)?:$title)),'-').'-'.bin2hex(random_bytes(3));Database::run('INSERT INTO discussions(user_id,category_id,title,slug,body) VALUES(?,?,?,?,?)',[auth()['id'],$category,$title,$slug,$body]);flash('success','Your discussion was submitted for moderation.');redirect('account');}
    public function comment(string $id):void{Auth::requireLogin();$discussion=Database::one("SELECT * FROM discussions WHERE id=? AND status='published'",[(int)$id]);$body=trim($_POST['body']??'');if(!$discussion||mb_strlen($body)<3){flash('error','Comment could not be added.');redirect('discussions');}Database::run('INSERT INTO discussion_comments(discussion_id,user_id,parent_id,body,status) VALUES(?,?,?,?,?)',[(int)$id,auth()['id'],($_POST['parent_id']??'')?:null,$body,'approved']);if((int)$discussion['user_id']!==(int)auth()['id'])Database::run('INSERT INTO notifications(user_id,type,title,message,url) VALUES(?,?,?,?,?)',[$discussion['user_id'],'discussion_reply','New reply to your discussion',auth()['full_name'].' replied to '.$discussion['title'],'/discussions/'.$discussion['slug']]);flash('success','Your reply was added.');redirect('discussions/'.$discussion['slug']);}
}
